#include <bits/stdc++.h>
using namespace std;

struct NumberTheory {
    struct Mod998 {
        static const long long MOD = 998244353LL;
        std::vector<long long> fact, inv_fact;

        void init(int n) {
            fact.resize(n + 1);
            inv_fact.resize(n + 1);
            fact[0] = 1;
            for (int i = 1; i <= n; i++) {
                fact[i] = (fact[i - 1] * i) % MOD;
            }
            inv_fact[n] = modInverse(fact[n], MOD);
            for (int i = n - 1; i >= 0; i--) {
                inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % MOD;
            }
        }

        long long modInverse(long long a, long long m) {
            long long m0 = m, t, q;
            long long x0 = 0, x1 = 1;
            if (m == 1) return 0;
            while (a > 1) {
                q = a / m;
                t = m;
                m = a % m; a = t;
                t = x0;
                x0 = x1 - q * x0;
                x1 = t;
            }
            if (x1 < 0) x1 += m0;
            return x1;
        }

        long long add(long long a, long long b) {
            long long res = a + b;
            if (res >= MOD) res -= MOD;
            return res;
        }

        long long subtract(long long a, long long b) {
            long long res = a - b;
            if (res < 0) res += MOD;
            return res;
        }

        long long mult(long long a, long long b) {
            return (a * b) % MOD;
        }

        long long ncr(int n, int r) {
            if (r < 0 || r > n) return 0;
            return fact[n] * inv_fact[r] % MOD * inv_fact[n - r] % MOD;
        }

        long long smallInv(int n) {
            return modInverse(n, MOD);
        }
    };
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;

    NumberTheory::Mod998 mod;
    int maxN = n + m + 10;
    mod.init(maxN);

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; p != 0; i++) {
        long long denom = mod.smallInv(n + m - i);
        p = mod.mult(p, n - i);
        p = mod.mult(p, denom);
        phaseSize = mod.add(phaseSize, p);
        if (i >= n) break; // To prevent infinite loop if p becomes 0
    }

    long long answer = 0;
    for (int k = 1; k <= n; k++) {
        long long numPhases = mod.mult(m + k, mod.smallInv(k));
        long long e = mod.mult(numPhases, phaseSize);
        long long term = mod.mult(mod.ncr(n, k), e);
        if (k % 2 == 1)
            answer = mod.add(answer, term);
        else
            answer = mod.subtract(answer, term);
    }

    cout << answer << "\n";

    return 0;
}
